INSERT INTO words (word_id, word, phonetic, part_of_speech, definitions_json, analysis_json, collocation, examples_json, word_family_json, secondary_meaning_note, difficulty, frequency_rank) VALUES
(500, 'convention', '/kənˈvenʃn/', 'noun', '{"zh-TW":["大會；慣例"],"en":["a large meeting or conference","a widely accepted practice"]}', '{"prefix":{"text":"con-","meaning":"together (一起)"},"root":{"text":"ven","meaning":"come (來)"},"suffix":{"text":"-tion","meaning":"action (動作)"},"logic":"一起來的行動，即「大會」。"}', 'convention center / industry convention / by convention', '[{"en":"The annual convention attracted 3,000 attendees.","zh-TW":"年度大會吸引了3,000位出席者。"},{"en":"By convention, the report is submitted quarterly.","zh-TW":"按照慣例，報告每季提交。"}]', '{"adjective":"conventional"}', NULL, 4, 500),
(501, 'conversation', '/ˌkɒnvərˈseɪʃən/', 'noun', '{"zh-TW":["對話；交談"],"en":["a talk between two or more people"]}', NULL, 'have a conversation / casual conversation', '[{"en":"We had a long conversation.","zh-TW":"我們進行了一場長談。"},{"en":"I overheard their conversation.","zh-TW":"我無意間聽到了他們的對話。"}]', '{"verb":"converse","adjective":"conversational"}', NULL, 4, 501),
(502, 'convert', '/kənˈvɜːrt/', 'verb', '{"zh-TW":["轉換；改變"],"en":["to change from one form or use to another"]}', '{"prefix":{"text":"con-","meaning":"completely (完全)"},"root":{"text":"vert","meaning":"turn (轉)"},"logic":"完全轉變，即「轉換」。"}', 'convert currency/data/file', '[{"en":"The warehouse was converted into office space.","zh-TW":"倉庫被改建為辦公空間。"},{"en":"Please convert the amounts to US dollars.","zh-TW":"請將金額轉換為美元。"}]', '{"noun":"conversion"}', NULL, 3, 502),
(503, 'convey', '/kənˈveɪ/', 'verb', '{"zh-TW":["傳達；運送"],"en":["to communicate a message or idea","to transport something"]}', '{"prefix":{"text":"con-","meaning":"together (一起)"},"root":{"text":"vey","meaning":"way/carry (路/攜帶)"},"logic":"一起帶走傳送，即「傳達」。"}', 'convey a message/meaning/impression', '[{"en":"The email failed to convey the urgency of the situation.","zh-TW":"電子郵件未能傳達情況的緊迫性。"},{"en":"Charts can convey complex data effectively.","zh-TW":"圖表可以有效傳達複雜數據。"}]', NULL, NULL, 2, 503),
(504, 'conviction', '/kənˈvɪkʃən/', 'noun', '{"zh-TW":["定罪；信念"],"en":["being found guilty of a crime"]}', NULL, 'criminal conviction / strong conviction', '[{"en":"He has no prior convictions.","zh-TW":"他沒有前科。"},{"en":"She spoke with strong conviction.","zh-TW":"她說話帶著堅定的信念。"}]', '{"verb":"convict"}', NULL, 4, 504),
(505, 'convince', '/kənˈvɪns/', 'verb', '{"zh-TW":["說服；使確信","說服"],"en":["to cause someone to believe something firmly","to make someone believe something"]}', '{"prefix":{"text":"con-","meaning":"completely (完全)"},"root":{"text":"vince","meaning":"conquer (征服)"},"logic":"完全征服某人的想法，即「說服」。"}', 'convince sb to do / convince sb that; convince someone to / hard to convince', '[{"en":"She convinced the board to approve the budget increase.","zh-TW":"她說服董事會批准增加預算。"},{"en":"The data convinced us that the strategy was working.","zh-TW":"數據使我們確信策略正在奏效。"},{"en":"She convinced me to try it.","zh-TW":"她說服我去嘗試。"},{"en":"I''m not convinced that''s the best option.","zh-TW":"我不確信那是最好的選擇。"}]', '{"adjective":"convincing"}', NULL, 3, 505),
(506, 'cook', '/kʊk/', 'verb', '{"zh-TW":["烹飪；廚師","烹飪；做飯"],"en":["to prepare food by heating","a person who cooks"]}', NULL, 'cook a meal / head cook; cook dinner / cook up', '[{"en":"She cooks dinner every evening.","zh-TW":"她每天晚上煮晚餐。"},{"en":"The restaurant hired a new head cook.","zh-TW":"餐廳聘請了一位新主廚。"},{"en":"Who''s cooking dinner tonight?","zh-TW":"今晚誰做飯？"},{"en":"She cooks really well.","zh-TW":"她做飯很好吃。"}]', '{"verb":"cook","noun":"cook","noun2":"cooking","noun3":"cooker"}', NULL, 1, 506),
(507, 'cookie', '/ˈkʊki/', 'noun', '{"zh-TW":["餅乾"],"en":["a small flat sweet cake"]}', NULL, 'chocolate chip cookie / cookie jar', '[{"en":"Would you like a cookie?","zh-TW":"你想要一塊餅乾嗎？"},{"en":"She baked cookies for the party.","zh-TW":"她為派對烤了餅乾。"}]', NULL, NULL, 2, 507),
(508, 'cool', '/kuːl/', 'adjective', '{"zh-TW":["涼爽的；冷靜的","涼的；酷的"],"en":["slightly cold","calm and relaxed","slightly cold; fashionable"]}', NULL, 'keep cool / cool down; cool down / keep cool', '[{"en":"Keep cool under pressure.","zh-TW":"在壓力下保持冷靜。"},{"en":"The weather is getting cooler.","zh-TW":"天氣變得越來越涼爽。"},{"en":"The weather is getting cool.","zh-TW":"天氣漸漸涼了。"},{"en":"That''s a really cool jacket.","zh-TW":"那件夾克真酷。"}]', '{"adjective":"cool","verb":"cool","noun":"coolness","adverb":"coolly"}', NULL, 1, 508),
(509, 'cooperate', '/kəʊˈɒpəreɪt/', 'verb', '{"zh-TW":["合作；配合","合作"],"en":["to work together toward a common goal"]}', '{"prefix":{"text":"co-","meaning":"together (一起)"},"root":{"text":"oper","meaning":"work (工作)"},"suffix":{"text":"-ate","meaning":"to do (做)"},"logic":"一起工作，即「合作」。"}', 'cooperate with / cooperate closely; cooperate with / cooperate fully', '[{"en":"Both departments must cooperate to meet the deadline.","zh-TW":"兩個部門必須合作以趕上截止日期。"},{"en":"The company cooperated fully with the investigation.","zh-TW":"公司全力配合調查。"},{"en":"The two companies agreed to cooperate on the project.","zh-TW":"兩家公司同意在該專案上合作。"},{"en":"Please cooperate with the investigation.","zh-TW":"請配合調查。"}]', '{"noun":"cooperation","adjective":"cooperative"}', NULL, 3, 509),
(510, 'coordinate', '/kəʊˈɔːrdɪneɪt/', 'verb', '{"zh-TW":["協調；統籌"],"en":["to organize different elements to work together effectively"]}', '{"prefix":{"text":"co-","meaning":"together (一起)"},"root":{"text":"ordin","meaning":"order (秩序)"},"suffix":{"text":"-ate","meaning":"to make (使)"},"logic":"使一起有秩序，即「協調」。"}', 'coordinate efforts/activities/schedules', '[{"en":"She coordinates all logistics for international shipments.","zh-TW":"她協調所有國際出貨的物流。"},{"en":"We need to coordinate our efforts across departments.","zh-TW":"我們需要跨部門協調努力。"}]', '{"noun":"coordination","noun2":"coordinator"}', NULL, 4, 510),
(511, 'cope', '/koʊp/', 'verb', '{"zh-TW":["應付；處理"],"en":["to deal with something effectively"]}', '{"root":{"text":"cope","meaning":"strike/deal with (對付)"},"logic":"源自古法語 couper（打擊），引申為應對。"}', 'cope with / unable to cope', '[{"en":"She learned to cope with stress through meditation.","zh-TW":"她學會透過冥想來應對壓力。"},{"en":"He couldn''t cope with the workload.","zh-TW":"他無法應付工作量。"}]', '{"noun":"coping"}', NULL, 1, 511),
(512, 'copy', '/ˈkɒpi/', 'noun', '{"zh-TW":["副本；複製"],"en":["a thing made to be the same as another"]}', NULL, 'make a copy / carbon copy', '[{"en":"Can you make a copy of this?","zh-TW":"你能複印一份嗎？"},{"en":"Keep a copy for your records.","zh-TW":"保留一份副本作為記錄。"}]', '{"verb":"copy"}', NULL, 1, 512),
(513, 'copyright', '/ˈkɒpiraɪt/', 'noun', '{"zh-TW":["著作權；版權"],"en":["the legal right to control creative work"]}', NULL, 'copyright law / copyright infringement', '[{"en":"The book is protected by copyright.","zh-TW":"這本書受著作權保護。"},{"en":"Copyright infringement is illegal.","zh-TW":"侵犯版權是違法的。"}]', NULL, NULL, 3, 513),
(514, 'corner', '/ˈkɔːrnər/', 'noun', '{"zh-TW":["角落；轉角","角落；拐角"],"en":["a point where two lines or surfaces meet","a place near where two roads meet","the point where two lines or walls meet"]}', NULL, 'around the corner / cut corners', '[{"en":"The coffee shop is around the corner.","zh-TW":"咖啡店就在轉角。"},{"en":"We cannot cut corners on safety.","zh-TW":"我們不能在安全方面偷工減料。"},{"en":"There''s a shop on the corner.","zh-TW":"拐角處有一家商店。"},{"en":"Success is just around the corner.","zh-TW":"成功就在眼前。"}]', '{"noun":"corner","verb":"corner"}', NULL, 2, 514),
(515, 'corporate', '/ˈkɔːrpərət/', 'adjective', '{"zh-TW":["企業的；公司的","公司的；企業的"],"en":["relating to a large company or group"]}', '{"root":{"text":"corpor","meaning":"body (身體)"},"suffix":{"text":"-ate","meaning":"having (具有)"},"logic":"具有團體身體（法人）的，即「企業的」。"}', 'corporate culture / corporate governance / corporate strategy; corporate culture / corporate responsibility', '[{"en":"The corporate headquarters is located in New York.","zh-TW":"公司總部位於紐約。"},{"en":"Strong corporate governance builds investor trust.","zh-TW":"良好的公司治理建立投資者信任。"},{"en":"The corporate headquarters is in New York.","zh-TW":"公司總部在紐約。"},{"en":"Corporate responsibility is increasingly important.","zh-TW":"企業責任越來越重要。"}]', '{"noun":"corporation"}', NULL, 3, 515),
(516, 'correct', '/kəˈrɛkt/', 'adjective', '{"zh-TW":["正確的；糾正","正確的"],"en":["right; without errors","to make right","right; without mistakes"]}', NULL, 'correct answer / correct a mistake; correct answer / politically correct', '[{"en":"Is this information correct?","zh-TW":"這個資訊正確嗎？"},{"en":"Please correct any errors in the report.","zh-TW":"請更正報告中的錯誤。"},{"en":"Your answer is correct.","zh-TW":"你的答案是正確的。"},{"en":"Please correct any errors.","zh-TW":"請改正任何錯誤。"}]', '{"adjective":"correct","verb":"correct","noun":"correction","adverb":"correctly"}', NULL, 3, 516),
(517, 'correspond', '/ˌkɒrɪˈspɒnd/', 'verb', '{"zh-TW":["對應；通信"],"en":["to be similar or equivalent to","to communicate by letter or email"]}', '{"prefix":{"text":"cor-","meaning":"together (一起)"},"root":{"text":"respond","meaning":"answer (回應)"},"logic":"一起回應，即「對應、通信」。"}', 'correspond to/with / correspond by email', '[{"en":"The results correspond to our initial predictions.","zh-TW":"結果與我們最初的預測相符。"},{"en":"We have been corresponding by email for months.","zh-TW":"我們已通過電子郵件通信數月。"}]', '{"noun":"correspondence"}', NULL, 4, 517),
(518, 'cost', '/kɒst/', 'noun', '{"zh-TW":["成本；費用"],"en":["the amount of money needed to buy or do something"]}', '{"root":{"text":"cost","meaning":"stand at a price (定價)"},"logic":"定價，即「成本」。"}', 'cost-effective / at all costs / reduce costs', '[{"en":"We need to reduce operating costs by 15%.","zh-TW":"我們需要將營運成本降低15%。"},{"en":"The total cost exceeded the original estimate.","zh-TW":"總成本超過了原始估算。"}]', '{"adjective":"costly"}', NULL, 1, 518),
(519, 'cotton', '/ˈkɒtən/', 'noun', '{"zh-TW":["棉花；棉布"],"en":["a soft white material used for making cloth"]}', NULL, 'cotton shirt / cotton candy', '[{"en":"This shirt is made of cotton.","zh-TW":"這件襯衫是棉做的。"},{"en":"Cotton is grown in warm climates.","zh-TW":"棉花生長在溫暖的氣候中。"}]', NULL, NULL, 2, 519),
(520, 'council', '/ˈkaʊnsl/', 'noun', '{"zh-TW":["委員會；議會"],"en":["an advisory or legislative body of people"]}', '{"prefix":{"text":"con-","meaning":"together (一起)"},"root":{"text":"cil","meaning":"call (召集)"},"logic":"一起被召集的人，即「委員會」。"}', 'city council / council meeting / council member', '[{"en":"The city council approved the new development plan.","zh-TW":"市議會批准了新的開發計畫。"},{"en":"A council meeting is scheduled for next Tuesday.","zh-TW":"委員會會議安排在下週二。"}]', NULL, NULL, 3, 520),
(521, 'counsel', '/ˈkaʊnsl/', 'noun', '{"zh-TW":["勸告；律師","建議"],"en":["advice given formally","a lawyer representing someone"]}', '{"prefix":{"text":"con-","meaning":"together (一起)"},"root":{"text":"sel","meaning":"take/consult (取/諮詢)"},"logic":"一起諮詢，即「勸告」。"}', 'legal counsel / seek counsel / general counsel', '[{"en":"The firm hired outside legal counsel for the case.","zh-TW":"公司為此案聘請了外部法律顧問。"},{"en":"I would counsel patience in this situation.","zh-TW":"我建議在這種情況下保持耐心。"}]', '{"noun":"counselor"}', NULL, 3, 521),
(522, 'count', '/kaʊnt/', 'verb', '{"zh-TW":["計算；重要"],"en":["to find the total number"]}', NULL, 'count on / count down', '[{"en":"Can you count to ten in French?","zh-TW":"你能用法語數到十嗎？"},{"en":"You can count on me.","zh-TW":"你可以依靠我。"}]', '{"noun":"count","adjective":"countless"}', NULL, 2, 522),
(523, 'counter', '/ˈkaʊntər/', 'noun', '{"zh-TW":["櫃台；計數器"],"en":["a flat surface in a kitchen or shop"]}', NULL, 'over the counter / counter offer', '[{"en":"Leave the keys on the counter.","zh-TW":"把鑰匙放在櫃台上。"},{"en":"The medicine is available over the counter.","zh-TW":"這個藥不需要處方就能買到。"}]', NULL, NULL, 3, 523),
(524, 'counterpart', '/ˈkaʊntərpɑːrt/', 'noun', '{"zh-TW":["對應的人或物"],"en":["a person or thing with the same function in a different situation"]}', NULL, 'overseas counterpart / business counterpart', '[{"en":"I met with my Japanese counterpart.","zh-TW":"我與我的日本對口人員會面。"},{"en":"Their product is superior to its counterparts.","zh-TW":"他們的產品優於同類產品。"}]', '{"noun":"counterpart"}', NULL, 4, 524),
(525, 'country', '/ˈkʌntri/', 'noun', '{"zh-TW":["國家；鄉村"],"en":["a nation","rural areas outside cities","a nation with its own government"]}', NULL, 'home country / country of origin; home country / country side', '[{"en":"Which country are you from?","zh-TW":"你來自哪個國家？"},{"en":"The product''s country of origin is Japan.","zh-TW":"產品的原產國是日本。"},{"en":"They live in the countryside.","zh-TW":"他們住在鄉下。"}]', '{"noun":"country","noun2":"countryside"}', NULL, 3, 525),
(526, 'county', '/ˈkaʊnti/', 'noun', '{"zh-TW":["郡；縣"],"en":["a region of a country"]}', NULL, 'county court / county fair', '[{"en":"She lives in Orange County.","zh-TW":"她住在橘郡。"},{"en":"The county fair is in August.","zh-TW":"縣集市在八月舉行。"}]', NULL, NULL, 2, 526),
(527, 'couple', '/ˈkʌpəl/', 'noun', '{"zh-TW":["一對；幾個","一對；一些"],"en":["two people together","a small number","two people together; a few"]}', NULL, 'a couple of / married couple', '[{"en":"I need a couple of days to finish.","zh-TW":"我需要幾天來完成。"},{"en":"The couple next door just moved in.","zh-TW":"隔壁那對夫妻剛搬進來。"},{"en":"A couple of days ago, I saw him.","zh-TW":"幾天前我看到他了。"},{"en":"They make a lovely couple.","zh-TW":"他們是很可愛的一對。"}]', '{"noun":"couple","verb":"couple"}', NULL, 2, 527),
(528, 'coupon', '/ˈkuːpɒn/', 'noun', '{"zh-TW":["優惠券；折價券"],"en":["a voucher giving a discount on a product"]}', '{"root":{"text":"coupon","meaning":"cut piece (切下的紙片)"},"logic":"源自法語 couper（剪），指剪下的折價券。"}', 'discount coupon / redeem a coupon', '[{"en":"I have a coupon for 20% off.","zh-TW":"我有一張八折優惠券。"},{"en":"Customers can redeem coupons at checkout.","zh-TW":"顧客可以在結帳時兌換優惠券。"}]', NULL, NULL, 2, 528),
(529, 'courage', '/ˈkɜːrɪdʒ/', 'noun', '{"zh-TW":["勇氣"],"en":["the ability to face danger without fear"]}', NULL, 'have the courage / take courage', '[{"en":"It takes courage to speak up.","zh-TW":"站出來發言需要勇氣。"},{"en":"She showed great courage.","zh-TW":"她展現了極大的勇氣。"}]', '{"adjective":"courageous"}', NULL, 3, 529),
(530, 'courageous', '/kəˈreɪdʒəs/', 'adjective', '{"zh-TW":["勇敢的"],"en":["not afraid of danger or difficulties"]}', '{"root":{"text":"courage","meaning":"heart (心)"},"suffix":{"text":"-ous","meaning":"full of (充滿)"},"logic":"充滿勇氣的，即「勇敢的」。"}', 'courageous act / courageous decision', '[{"en":"It was a courageous decision to speak up.","zh-TW":"站出來發聲是勇敢的決定。"},{"en":"The firefighters were incredibly courageous.","zh-TW":"消防隊員們非常英勇。"}]', '{"noun":"courage","adverb":"courageously"}', NULL, 4, 530),
(531, 'course', '/kɔːrs/', 'noun', '{"zh-TW":["課程；過程"],"en":["a series of lessons","a direction or path"]}', NULL, 'of course / training course', '[{"en":"I enrolled in a training course.","zh-TW":"我報名了一個培訓課程。"},{"en":"Of course, I will help you.","zh-TW":"當然，我會幫你。"}]', '{"noun":"course"}', NULL, 2, 531),
(532, 'court', '/kɔːrt/', 'noun', '{"zh-TW":["法庭；球場"],"en":["a place where legal cases are heard"]}', NULL, 'go to court / tennis court', '[{"en":"The case went to court.","zh-TW":"案件上了法庭。"},{"en":"We booked a tennis court.","zh-TW":"我們預訂了一個網球場。"}]', NULL, NULL, 2, 532),
(533, 'cousin', '/ˈkʌzən/', 'noun', '{"zh-TW":["表兄弟姊妹"],"en":["the child of your aunt or uncle"]}', NULL, 'first cousin / distant cousin', '[{"en":"My cousin lives in Canada.","zh-TW":"我表哥住在加拿大。"},{"en":"We''re first cousins.","zh-TW":"我們是表兄弟。"}]', NULL, NULL, 2, 533),
(534, 'cover', '/ˈkʌvər/', 'verb', '{"zh-TW":["覆蓋；涵蓋"],"en":["to place something over","to include or deal with"]}', NULL, 'cover the cost / cover a topic', '[{"en":"Insurance will cover the cost.","zh-TW":"保險會支付這筆費用。"},{"en":"The report covers all major issues.","zh-TW":"報告涵蓋了所有主要問題。"}]', '{"verb":"cover","noun":"cover","noun2":"coverage"}', NULL, 2, 534),
(535, 'cow', '/kaʊ/', 'noun', '{"zh-TW":["牛；母牛"],"en":["a large female farm animal that produces milk"]}', NULL, 'dairy cow / cow milk', '[{"en":"The farmer milks the cows every morning.","zh-TW":"農夫每天早上擠牛奶。"},{"en":"Cows eat grass in the field.","zh-TW":"牛在田裡吃草。"}]', NULL, NULL, 1, 535),
(536, 'crack', '/kræk/', 'noun', '{"zh-TW":["裂縫；破裂聲"],"en":["a line where something is broken"]}', NULL, 'crack down / crack open', '[{"en":"There''s a crack in the wall.","zh-TW":"牆上有一條裂縫。"},{"en":"The government cracked down on crime.","zh-TW":"政府嚴厲打擊犯罪。"}]', '{"verb":"crack"}', NULL, 2, 536),
(537, 'craft', '/kræft/', 'noun', '{"zh-TW":["工藝；手藝"],"en":["an activity involving skilled making of things by hand","an activity involving skill in making things by hand"]}', '{"root":{"text":"craft","meaning":"strength/skill (力量/技藝)"},"logic":"源自古英語 cræft（力量、技能）。"}', 'arts and crafts / craft beer; arts and crafts / craft beer / master one''s craft', '[{"en":"She''s skilled in traditional crafts.","zh-TW":"她擅長傳統工藝。"},{"en":"Craft beer has become very popular.","zh-TW":"精釀啤酒變得非常受歡迎。"},{"en":"She learned the craft of pottery making.","zh-TW":"她學會了陶藝的手藝。"},{"en":"Local crafts are sold at the market.","zh-TW":"當地手工藝品在市場販售。"}]', '{"noun2":"craftsman","adjective":"crafty","noun":"craftsman","verb":"craft"}', NULL, 2, 537),
(538, 'crash', '/kræʃ/', 'noun', '{"zh-TW":["碰撞；崩潰"],"en":["a violent collision; a sudden failure"]}', NULL, 'car crash / system crash', '[{"en":"There was a car crash on the highway.","zh-TW":"高速公路上發生了車禍。"},{"en":"The computer crashed again.","zh-TW":"電腦又當機了。"}]', '{"verb":"crash"}', NULL, 2, 538),
(539, 'crazy', '/ˈkreɪzi/', 'adjective', '{"zh-TW":["瘋狂的"],"en":["very foolish; mentally ill"]}', NULL, 'go crazy / crazy about', '[{"en":"That''s a crazy idea!","zh-TW":"那是個瘋狂的想法！"},{"en":"She''s crazy about music.","zh-TW":"她對音樂非常著迷。"}]', NULL, NULL, 2, 539),
(540, 'cream', '/kriːm/', 'noun', '{"zh-TW":["奶油；乳霜"],"en":["the thick white liquid from milk"]}', NULL, 'ice cream / cream cheese', '[{"en":"I''d like cream in my coffee.","zh-TW":"我的咖啡要加奶油。"},{"en":"Apply this cream twice daily.","zh-TW":"每天塗兩次這個乳霜。"}]', '{"adjective":"creamy"}', NULL, 2, 540),
(541, 'create', '/kriˈeɪt/', 'verb', '{"zh-TW":["創造；建立"],"en":["to bring something into existence"]}', '{"root":{"text":"cre","meaning":"grow/make (成長/製造)"},"suffix":{"text":"-ate","meaning":"to do (做)"},"logic":"使成長出來，即「創造」。"}', 'create value/opportunities/jobs', '[{"en":"The merger will create the largest company in the sector.","zh-TW":"合併將創建該行業最大的公司。"},{"en":"Innovation creates new business opportunities.","zh-TW":"創新創造了新的商業機會。"}]', '{"noun":"creation","adjective":"creative","noun2":"creativity"}', NULL, 2, 541),
(542, 'creative', '/kriˈeɪtɪv/', 'adjective', '{"zh-TW":["有創意的"],"en":["involving the use of imagination to produce new ideas"]}', '{"root":{"text":"creat","meaning":"make (創造)"},"suffix":{"text":"-ive","meaning":"having quality of (具有…特質)"},"logic":"具有創造特質的。"}', 'creative thinking / creative director', '[{"en":"She found a creative solution to the problem.","zh-TW":"她找到了一個有創意的解決方案。"},{"en":"The job requires creative thinking.","zh-TW":"這份工作需要創意思考。"}]', '{"noun":"creativity","verb":"create","noun2":"creation"}', NULL, 3, 542),
(543, 'creature', '/ˈkriːtʃər/', 'noun', '{"zh-TW":["生物；動物"],"en":["any living thing that is not a plant"]}', NULL, 'living creature / sea creature', '[{"en":"Strange creatures live in the deep sea.","zh-TW":"奇怪的生物生活在深海中。"},{"en":"Every creature deserves respect.","zh-TW":"每一個生物都值得被尊重。"}]', NULL, NULL, 3, 543),
(544, 'credential', '/krɪˈdɛnʃəl/', 'noun', '{"zh-TW":["資格證明；證書"],"en":["qualifications or achievements that prove capability"]}', NULL, 'professional credentials / verify credentials', '[{"en":"Please verify the candidate''s credentials.","zh-TW":"請驗證候選人的資歷。"},{"en":"His credentials include an MBA and CPA.","zh-TW":"他的資歷包括MBA和CPA。"}]', '{"noun":"credential","adjective":"credentialed"}', NULL, 4, 544),
(545, 'credit', '/ˈkredɪt/', 'noun', '{"zh-TW":["信用；學分","功勞","信用；學分；功勞"],"en":["the ability to borrow money","praise or acknowledgment","the ability to buy now and pay later"]}', '{"root":{"text":"cred","meaning":"believe (相信)"},"suffix":{"text":"-it","meaning":"thing (事物)"},"logic":"被相信（可還款）的，即「信用」。"}', 'credit card / credit rating / take credit for; credit card / take credit', '[{"en":"The company has a strong credit rating.","zh-TW":"公司擁有良好的信用評級。"},{"en":"Credit sales increased by 12% this quarter.","zh-TW":"本季度信用銷售增長了12%。"},{"en":"She paid by credit card.","zh-TW":"她用信用卡付款。"},{"en":"Give credit where it''s due.","zh-TW":"該給的功勞要給。"}]', '{"noun":"creditor","adjective":"credible","verb":"credit","noun2":"creditor"}', NULL, 2, 545),
(546, 'crew', '/kruː/', 'noun', '{"zh-TW":["全體船員；團隊"],"en":["a group of people working together"]}', NULL, 'flight crew / camera crew', '[{"en":"The flight crew was very friendly.","zh-TW":"機組人員非常友善。"},{"en":"The film crew arrived early.","zh-TW":"攝影團隊很早就到了。"}]', NULL, NULL, 1, 546),
(547, 'crime', '/kraɪm/', 'noun', '{"zh-TW":["犯罪；罪行"],"en":["an illegal act"]}', NULL, 'commit a crime / crime rate', '[{"en":"Crime rates have decreased.","zh-TW":"犯罪率下降了。"},{"en":"He committed a serious crime.","zh-TW":"他犯了嚴重的罪行。"}]', '{"noun2":"criminal","adjective":"criminal"}', NULL, 2, 547),
(548, 'criminal', '/ˈkrɪmɪnəl/', 'noun', '{"zh-TW":["罪犯"],"en":["a person who has committed a crime"]}', NULL, 'criminal record / criminal law', '[{"en":"The criminal was arrested.","zh-TW":"罪犯被逮捕了。"},{"en":"He has a criminal record.","zh-TW":"他有犯罪紀錄。"}]', '{"noun2":"crime","adjective":"criminal"}', NULL, 3, 548),
(549, 'crisis', '/ˈkraɪsɪs/', 'noun', '{"zh-TW":["危機"],"en":["a time of great difficulty or danger"]}', NULL, 'financial crisis / crisis management', '[{"en":"The country is facing an economic crisis.","zh-TW":"國家正面臨經濟危機。"},{"en":"Good leaders handle crises well.","zh-TW":"好的領導者善於處理危機。"}]', NULL, NULL, 2, 549);
