(550, 'criteria', '/kraɪˈtɪəriə/', 'noun', '{"zh-TW":["標準；準則（複數）","標準（複數）"],"en":["standards by which something is judged","principles used to judge or decide something"]}', '{"root":{"text":"crit","meaning":"judge (判斷)"},"suffix":{"text":"-eria","meaning":"plural (複數)"},"logic":"用來判斷的標準，即「準則」。"}', 'meet criteria / selection criteria / evaluation criteria; meet the criteria / selection criteria / strict criteria', '[{"en":"Applicants must meet all the selection criteria.","zh-TW":"申請者必須符合所有篩選標準。"},{"en":"What criteria did you use to evaluate the proposals?","zh-TW":"你用什麼標準來評估提案？"},{"en":"Applicants must meet all the criteria.","zh-TW":"申請者必須符合所有標準。"},{"en":"What criteria did you use to make the decision?","zh-TW":"你用什麼標準做出決定？"}]', '{"noun":"criterion","noun_singular":"criterion"}', NULL, 3, 550),
(551, 'criterion', '/kraɪˈtɪəriən/', 'noun', '{"zh-TW":["標準；準則（單數）"],"en":["a principle or standard by which something is judged"]}', '{"root":{"text":"crit","meaning":"judge (判斷)"},"suffix":{"text":"-erion","meaning":"thing (事物)"},"logic":"用來判斷的事物，即「標準」。"}', 'main criterion / selection criterion / meet the criterion', '[{"en":"Price is not the only criterion for selection.","zh-TW":"價格不是選擇的唯一標準。"},{"en":"The main criterion is prior experience.","zh-TW":"主要標準是先前的經驗。"}]', '{"noun":"criteria"}', NULL, 3, 551),
(552, 'critic', '/ˈkrɪtɪk/', 'noun', '{"zh-TW":["評論家；批評者"],"en":["a person who judges the quality of art, music, or literature"]}', '{"root":{"text":"crit","meaning":"judge (判斷)"},"suffix":{"text":"-ic","meaning":"person (人)"},"logic":"做出判斷的人，即「評論家」。"}', 'film critic / art critic / harsh critic', '[{"en":"The critics praised the new film.","zh-TW":"影評人稱讚這部新電影。"},{"en":"He is a well-known food critic.","zh-TW":"他是知名的美食評論家。"}]', '{"noun":"criticism","adjective":"critical","verb":"criticize"}', NULL, 2, 552),
(553, 'critical', '/ˈkrɪtɪkəl/', 'adjective', '{"zh-TW":["批評的；關鍵的；危急的"],"en":["very important; expressing disapproval"]}', NULL, 'critical thinking / critical condition', '[{"en":"Critical thinking is an essential skill.","zh-TW":"批判性思維是必備技能。"},{"en":"The patient is in critical condition.","zh-TW":"病人情況危急。"}]', '{"noun":"criticism","verb":"criticize","noun2":"critic"}', NULL, 3, 553),
(554, 'crop', '/krɒp/', 'noun', '{"zh-TW":["作物；莊稼"],"en":["plants grown for food"]}', NULL, 'crop rotation / cash crop', '[{"en":"The drought destroyed the crops.","zh-TW":"乾旱摧毀了農作物。"},{"en":"Rice is the main crop here.","zh-TW":"稻米是這裡的主要作物。"}]', NULL, NULL, 1, 554),
(555, 'cross', '/krɒs/', 'verb', '{"zh-TW":["穿越；橫過"],"en":["to go from one side to the other"]}', NULL, 'cross the border / cross-reference', '[{"en":"Look both ways before you cross.","zh-TW":"過馬路前先看兩邊。"},{"en":"Please cross-reference the data.","zh-TW":"請交叉比對資料。"}]', '{"verb":"cross","noun":"crossing","adjective":"cross"}', NULL, 2, 555),
(556, 'crowd', '/kraʊd/', 'noun', '{"zh-TW":["人群"],"en":["a large number of people gathered together"]}', NULL, 'crowd of people / stand out from the crowd', '[{"en":"A large crowd gathered outside.","zh-TW":"一大群人聚集在外面。"},{"en":"She stood out from the crowd.","zh-TW":"她在人群中脫穎而出。"}]', '{"adjective":"crowded"}', NULL, 2, 556),
(557, 'crucial', '/ˈkruːʃl/', 'adjective', '{"zh-TW":["關鍵的；至關重要的"],"en":["of great importance; critical","of great importance; decisive"]}', '{"root":{"text":"cruc","meaning":"cross (十字)"},"suffix":{"text":"-ial","meaning":"relating to (有關的)"},"logic":"在十字路口的（決定性的），即「關鍵的」。"}', 'crucial role/factor/decision; crucial role / crucial decision / crucial moment', '[{"en":"Timing is crucial for the success of this launch.","zh-TW":"時機對此次發布的成功至關重要。"},{"en":"Communication plays a crucial role in teamwork.","zh-TW":"溝通在團隊合作中扮演關鍵角色。"},{"en":"Teamwork is crucial to success.","zh-TW":"團隊合作對成功至關重要。"},{"en":"This is a crucial moment in the negotiations.","zh-TW":"這是談判中的關鍵時刻。"}]', '{"adverb":"crucially"}', NULL, 3, 557),
(558, 'cruel', '/ˈkruːəl/', 'adjective', '{"zh-TW":["殘忍的"],"en":["causing pain or suffering deliberately"]}', NULL, 'cruel treatment / cruel joke', '[{"en":"It''s cruel to hurt animals.","zh-TW":"傷害動物是殘忍的。"},{"en":"Don''t be so cruel.","zh-TW":"別這麼殘忍。"}]', '{"noun":"cruelty","adverb":"cruelly"}', NULL, 2, 558),
(559, 'crush', '/krʌʃ/', 'verb', '{"zh-TW":["壓碎；壓垮"],"en":["to press something so hard that it breaks"]}', NULL, 'crush ice / have a crush on', '[{"en":"Crush the garlic before adding it.","zh-TW":"加入前先壓碎大蒜。"},{"en":"She has a crush on her classmate.","zh-TW":"她暗戀她的同學。"}]', '{"noun":"crush"}', NULL, 2, 559),
(560, 'cry', '/kraɪ/', 'verb', '{"zh-TW":["哭；喊叫"],"en":["to produce tears","to shout","to produce tears from your eyes"]}', NULL, 'cry out / a far cry from; cry out / far cry', '[{"en":"This result is a far cry from what we expected.","zh-TW":"這個結果跟我們預期的相差甚遠。"},{"en":"She cried tears of joy.","zh-TW":"她喜極而泣。"},{"en":"The baby started to cry.","zh-TW":"寶寶開始哭了。"},{"en":"She cried out for help.","zh-TW":"她大聲呼救。"}]', '{"verb":"cry","noun":"cry"}', NULL, 1, 560),
(561, 'cultivate', '/ˈkʌltɪveɪt/', 'verb', '{"zh-TW":["培養；培育","培養；耕種"],"en":["to develop or improve by education or training","to grow plants","to develop a quality or skill"]}', '{"root":{"text":"cult","meaning":"tend/grow (耕種)"},"suffix":{"text":"-ivate","meaning":"to make (使)"},"logic":"使耕種成長，即「培養」。"}', 'cultivate relationships/skills/talent; cultivate relationships / cultivate land', '[{"en":"We cultivate long-term relationships with our partners.","zh-TW":"我們培養與合作夥伴的長期關係。"},{"en":"The program helps cultivate future leaders.","zh-TW":"該計畫幫助培養未來的領導者。"},{"en":"Farmers cultivate rice in this region.","zh-TW":"農民在這個地區種植稻米。"},{"en":"She cultivated strong relationships with clients.","zh-TW":"她培養了與客戶的良好關係。"}]', '{"noun":"cultivation"}', NULL, 3, 561),
(562, 'cultural', '/ˈkʌltʃərəl/', 'adjective', '{"zh-TW":["文化的"],"en":["relating to the ideas and customs of a society"]}', NULL, 'cultural difference / cultural exchange', '[{"en":"There are cultural differences between countries.","zh-TW":"國家之間存在文化差異。"},{"en":"The city offers many cultural activities.","zh-TW":"這座城市提供許多文化活動。"}]', '{"noun":"culture","adverb":"culturally"}', NULL, 3, 562),
(563, 'cup', '/kʌp/', 'noun', '{"zh-TW":["杯子"],"en":["a small container for drinking"]}', NULL, 'cup of tea / World Cup', '[{"en":"Would you like a cup of tea?","zh-TW":"你想來杯茶嗎？"},{"en":"The World Cup is held every four years.","zh-TW":"世界盃每四年舉行一次。"}]', NULL, NULL, 1, 563),
(564, 'curator', '/kjʊˈreɪtər/', 'noun', '{"zh-TW":["策展人；館長"],"en":["a person in charge of a museum or gallery collection"]}', '{"root":{"text":"cur","meaning":"care (照料)"},"suffix":{"text":"-ator","meaning":"person who (…的人)"},"logic":"照料收藏品的人，即「策展人」。"}', 'museum curator / guest curator', '[{"en":"The curator organized a new exhibition.","zh-TW":"策展人組織了一場新展覽。"},{"en":"She works as a curator at the national museum.","zh-TW":"她在國家博物館擔任策展人。"}]', '{"verb":"curate","noun":"curation"}', NULL, 3, 564),
(565, 'curb', '/kɜːrb/', 'verb', '{"zh-TW":["抑制；控制"],"en":["to restrain or keep in check"]}', '{"root":{"text":"curb","meaning":"curve/bend (彎曲)"},"logic":"彎曲拉回，即「抑制」。"}', 'curb spending/inflation/emissions', '[{"en":"The government introduced measures to curb inflation.","zh-TW":"政府推出了抑制通膨的措施。"},{"en":"We need to curb unnecessary spending.","zh-TW":"我們需要控制不必要的支出。"}]', NULL, NULL, 1, 565),
(566, 'cure', '/kjʊr/', 'noun', '{"zh-TW":["治療；療法"],"en":["a treatment that makes someone well"]}', NULL, 'cure for / no cure', '[{"en":"There is no cure for this disease yet.","zh-TW":"這種疾病目前還沒有治療方法。"},{"en":"Prevention is better than cure.","zh-TW":"預防勝於治療。"}]', '{"verb":"cure","adjective":"curable"}', NULL, 1, 566),
(567, 'curious', '/ˈkjʊriəs/', 'adjective', '{"zh-TW":["好奇的"],"en":["wanting to know or learn something","eager to know or learn something"]}', '{"root":{"text":"cur","meaning":"care (關心)"},"suffix":{"text":"-ious","meaning":"full of (充滿)"},"logic":"充滿關心想了解的，即「好奇的」。"}', 'curious about / curious mind', '[{"en":"Children are naturally curious.","zh-TW":"孩子們天生好奇。"},{"en":"I''m curious about your trip.","zh-TW":"我很好奇你的旅行。"},{"en":"Children are naturally curious about the world.","zh-TW":"孩子天生對世界充滿好奇。"},{"en":"I''m curious to know what happened.","zh-TW":"我很好奇發生了什麼事。"}]', '{"noun":"curiosity","adverb":"curiously"}', NULL, 3, 567),
(568, 'currency', '/ˈkʌrənsi/', 'noun', '{"zh-TW":["貨幣；通貨"],"en":["a system of money in general use"]}', '{"root":{"text":"curr","meaning":"run (流通)"},"suffix":{"text":"-ency","meaning":"state (狀態)"},"logic":"流通的狀態，即「貨幣」。"}', 'foreign currency / currency exchange / digital currency', '[{"en":"Please specify payment in local currency.","zh-TW":"請以當地貨幣指定付款。"},{"en":"Currency exchange rates fluctuate daily.","zh-TW":"匯率每天波動。"}]', NULL, NULL, 3, 568),
(569, 'current', '/ˈkʌrənt/', 'adjective', '{"zh-TW":["目前的；現行的"],"en":["happening or existing now"]}', '{"root":{"text":"curr","meaning":"run (流動)"},"suffix":{"text":"-ent","meaning":"being (存在的)"},"logic":"正在流動存在的，即「目前的」。"}', 'current situation/policy/trend', '[{"en":"The current policy expires at the end of this year.","zh-TW":"現行政策於今年年底到期。"},{"en":"We need to analyze current market trends.","zh-TW":"我們需要分析目前的市場趨勢。"}]', '{"adverb":"currently"}', NULL, 3, 569),
(570, 'curriculum', '/kəˈrɪkjʊləm/', 'noun', '{"zh-TW":["課程；課程表"],"en":["the subjects in a course of study"]}', NULL, 'curriculum vitae / training curriculum; school curriculum / curriculum design', '[{"en":"Please submit your curriculum vitae.","zh-TW":"請提交你的履歷。"},{"en":"The training curriculum covers all essentials.","zh-TW":"培訓課程涵蓋了所有必備項目。"},{"en":"The school updated its curriculum.","zh-TW":"學校更新了課程。"},{"en":"Math is part of the core curriculum.","zh-TW":"數學是核心課程的一部分。"}]', '{"noun":"curriculum","adjective":"curricular","adjective2":"extracurricular"}', NULL, 4, 570),
(571, 'curve', '/kɜːrv/', 'noun', '{"zh-TW":["曲線；彎道"],"en":["a smooth bending line"]}', NULL, 'learning curve / sharp curve', '[{"en":"There''s a sharp curve in the road.","zh-TW":"路上有一個急彎。"},{"en":"The learning curve is steep.","zh-TW":"學習曲線很陡峭。"}]', '{"adjective":"curved"}', NULL, 2, 571),
(572, 'custody', '/ˈkʌstədi/', 'noun', '{"zh-TW":["保管；監護","監護權；拘留"],"en":["the protective care or guardianship of something","the legal right to care for a child; being held by police"]}', '{"root":{"text":"cust","meaning":"guard (守護)"},"suffix":{"text":"-ody","meaning":"state (狀態)"},"logic":"守護的狀態，即「保管」。"}', 'in custody / custody of assets / safe custody; in custody / child custody', '[{"en":"Securities are held in safe custody by the bank.","zh-TW":"證券由銀行安全保管。"},{"en":"The documents are in the custody of the legal department.","zh-TW":"文件由法務部門保管。"},{"en":"She was awarded custody of the children.","zh-TW":"她獲得了孩子的監護權。"},{"en":"The suspect is in police custody.","zh-TW":"嫌疑人被警方拘留。"}]', '{"noun":"custodian"}', NULL, 3, 572),
(573, 'custom', '/ˈkʌstəm/', 'noun', '{"zh-TW":["習慣；海關","客製"],"en":["a traditional practice","duties charged on imports/exports"]}', '{"root":{"text":"custom","meaning":"habit/accustomed (習慣)"},"logic":"習慣的做法，即「習慣、海關」。"}', 'customs duty / local customs / custom-made', '[{"en":"The goods were held at customs for inspection.","zh-TW":"貨物在海關被扣留檢查。"},{"en":"We offer custom solutions tailored to your needs.","zh-TW":"我們提供量身定制的客製化解決方案。"}]', '{"noun":"customer","adjective":"customary","verb":"customize"}', NULL, 2, 573),
(574, 'customer', '/ˈkʌstəmər/', 'noun', '{"zh-TW":["顧客","顧客；客戶"],"en":["a person who buys goods or services"]}', '{"root":{"text":"custom","meaning":"habit (習慣)"},"suffix":{"text":"-er","meaning":"person who (…的人)"},"logic":"有消費習慣的人，即「顧客」。"}', 'regular customer / customer service; customer service / loyal customer', '[{"en":"The customer is always right.","zh-TW":"顧客永遠是對的。"},{"en":"We value our loyal customers.","zh-TW":"我們重視忠實顧客。"},{"en":"The customer asked for a refund.","zh-TW":"顧客要求退款。"}]', '{"noun":"custom","adjective":"customary"}', NULL, 3, 574),
(575, 'cut', '/kʌt/', 'verb', '{"zh-TW":["切；削減"],"en":["to divide with a sharp instrument","to reduce"]}', NULL, 'cut costs / cut back', '[{"en":"We need to cut costs by 10%.","zh-TW":"我們需要削減10%的成本。"},{"en":"The company cut 200 jobs.","zh-TW":"公司裁減了200個職位。"}]', '{"verb":"cut","noun":"cut","noun2":"cutback"}', NULL, 1, 575),
(576, 'cute', '/kjuːt/', 'adjective', '{"zh-TW":["可愛的"],"en":["attractive in a pretty way"]}', NULL, 'cute baby / cute outfit', '[{"en":"What a cute puppy!","zh-TW":"好可愛的小狗！"},{"en":"That''s a cute outfit.","zh-TW":"那套衣服很可愛。"}]', '{"noun":"cuteness"}', NULL, 1, 576),
(577, 'cybersecurity', '/ˌsaɪbərsɪˈkjʊrɪti/', 'noun', '{"zh-TW":["網路安全"],"en":["protection of computers and networks from attack"]}', NULL, 'cybersecurity threat / cybersecurity expert', '[{"en":"Cybersecurity is a growing concern.","zh-TW":"網路安全是日益受關注的議題。"},{"en":"She works in cybersecurity.","zh-TW":"她從事網路安全工作。"}]', NULL, NULL, 5, 577),
(578, 'cycle', '/ˈsaɪkl/', 'noun', '{"zh-TW":["週期；循環","循環；周期；自行車"],"en":["a series of events that are regularly repeated","a series of events that repeat"]}', '{"root":{"text":"cycl","meaning":"circle (圓)"},"suffix":{"text":"-e","meaning":"noun ending"},"logic":"圓形的重複，即「週期」。"}', 'business cycle / product life cycle / billing cycle; life cycle / business cycle', '[{"en":"The business cycle affects hiring decisions.","zh-TW":"商業週期影響招聘決策。"},{"en":"The product is at the end of its life cycle.","zh-TW":"產品已處於其生命週期的末端。"},{"en":"The seasons follow a cycle.","zh-TW":"季節遵循一個循環。"},{"en":"She cycles to work every day.","zh-TW":"她每天騎自行車上班。"}]', '{"adjective":"cyclical","verb":"cycle","noun2":"cyclist"}', NULL, 2, 578),
(579, 'cyclone', '/ˈsaɪkloʊn/', 'noun', '{"zh-TW":["氣旋；颶風"],"en":["a violent rotating windstorm"]}', '{"root":{"text":"cycl","meaning":"circle (圓)"},"suffix":{"text":"-one","meaning":"thing (物)"},"logic":"旋轉如圓的風暴。"}', 'tropical cyclone / cyclone warning', '[{"en":"The cyclone caused widespread destruction.","zh-TW":"氣旋造成大範圍的破壞。"},{"en":"A tropical cyclone is approaching the coast.","zh-TW":"一個熱帶氣旋正在逼近海岸。"}]', '{"adjective":"cyclonic"}', NULL, 3, 579),
(580, 'dad', '/dæd/', 'noun', '{"zh-TW":["爸爸"],"en":["a father"]}', NULL, 'my dad / dad joke', '[{"en":"My dad taught me to drive.","zh-TW":"我爸爸教我開車。"},{"en":"He''s a great dad.","zh-TW":"他是個好爸爸。"}]', NULL, NULL, 1, 580),
(581, 'daily', '/ˈdeɪli/', 'adjective', '{"zh-TW":["每日的"],"en":["happening every day"]}', NULL, 'daily routine / daily life', '[{"en":"Exercise is part of my daily routine.","zh-TW":"運動是我日常作息的一部分。"},{"en":"The newspaper is published daily.","zh-TW":"報紙每天出版。"}]', NULL, NULL, 2, 581),
(582, 'damage', '/ˈdæmɪdʒ/', 'noun / verb', '{"zh-TW":["損害；損壞"],"en":["physical harm that impairs value or usefulness"]}', NULL, 'cause/suffer damage', '[{"en":"The storm caused severe damage to the building.","zh-TW":"暴風雨對建築物造成了嚴重損害。"},{"en":"Smoking can damage your health.","zh-TW":"吸菸會損害你的健康。"}]', '{"noun":"damage","verb":"damage","adjective":"damaged"}', NULL, 2, 582),
(583, 'dance', '/dæns/', 'verb', '{"zh-TW":["跳舞；舞蹈"],"en":["to move rhythmically to music"]}', NULL, 'dance class / dance floor', '[{"en":"They danced at the company gala.","zh-TW":"他們在公司晚會上跳舞。"},{"en":"She teaches dance classes on weekends.","zh-TW":"她週末教舞蹈課。"}]', '{"verb":"dance","noun":"dance","noun2":"dancer","noun3":"dancing"}', NULL, 2, 583),
(584, 'danger', '/ˈdeɪndʒər/', 'noun', '{"zh-TW":["危險"],"en":["the possibility of harm or damage","the possibility of harm or death"]}', NULL, 'in danger / danger zone; in danger / out of danger', '[{"en":"Workers are in danger without proper equipment.","zh-TW":"沒有適當裝備，工人會有危險。"},{"en":"There is a danger of flooding.","zh-TW":"有發生洪水的危險。"},{"en":"The building is in danger of collapsing.","zh-TW":"這棟建築有倒塌的危險。"},{"en":"The patient is out of danger now.","zh-TW":"病人已經脫離危險了。"}]', '{"noun":"danger","adjective":"dangerous","adverb":"dangerously","verb":"endanger"}', NULL, 2, 584),
(585, 'dark', '/dɑːrk/', 'adjective', '{"zh-TW":["黑暗的；深色的"],"en":["with little or no light","closer to black"]}', NULL, 'in the dark / dark color; in the dark / dark side', '[{"en":"We were kept in the dark about the changes.","zh-TW":"我們被蒙在鼓裡不知道有變動。"},{"en":"She prefers dark colors for business wear.","zh-TW":"她上班穿著偏好深色系。"},{"en":"It gets dark early in winter.","zh-TW":"冬天天黑得早。"},{"en":"She has dark brown hair.","zh-TW":"她有深棕色的頭髮。"}]', '{"adjective":"dark","noun":"darkness","verb":"darken","adverb":"darkly"}', NULL, 1, 585),
(586, 'data', '/ˈdeɪtə/', 'noun', '{"zh-TW":["資料；數據"],"en":["facts and information collected together"]}', NULL, 'data analysis / big data', '[{"en":"We need more data to decide.","zh-TW":"我們需要更多數據來做決定。"},{"en":"Big data is transforming business.","zh-TW":"大數據正在改變商業。"}]', NULL, NULL, 1, 586),
(587, 'daughter', '/ˈdɔːtər/', 'noun', '{"zh-TW":["女兒"],"en":["a female child"]}', NULL, 'daughter company / eldest daughter; eldest daughter / daughter-in-law', '[{"en":"His daughter works at the same company.","zh-TW":"他的女兒在同一家公司工作。"},{"en":"The daughter company handles overseas sales.","zh-TW":"子公司負責海外銷售。"},{"en":"They have two daughters.","zh-TW":"他們有兩個女兒。"},{"en":"My daughter is ten years old.","zh-TW":"我女兒十歲了。"}]', '{"noun":"daughter"}', NULL, 3, 587),
(588, 'dead', '/dɛd/', 'adjective', '{"zh-TW":["死的；無生命的"],"en":["no longer alive","not working"]}', NULL, 'deadline / dead end; dead end / dead silence', '[{"en":"My phone battery is dead.","zh-TW":"我的手機沒電了。"},{"en":"The negotiations reached a dead end.","zh-TW":"談判陷入了僵局。"},{"en":"The flowers are dead.","zh-TW":"花都枯死了。"},{"en":"We reached a dead end.","zh-TW":"我們走到了死路。"}]', '{"adjective":"dead","noun":"death","verb":"die","adjective2":"deadly"}', NULL, 1, 588),
(589, 'deadline', '/ˈdedlaɪn/', 'noun', '{"zh-TW":["截止期限；最後期限","截止期限"],"en":["a date or time by which something must be done","the latest time by which something must be completed"]}', '{"root":{"text":"dead","meaning":"absolute (絕對)"},"suffix":{"text":"line","meaning":"line (線)"},"logic":"絕對不能越過的時間線。"}', 'meet/miss a deadline; meet the deadline / miss the deadline / tight deadline', '[{"en":"The deadline for applications is next Friday.","zh-TW":"申請的截止日期是下週五。"},{"en":"We need to meet the deadline.","zh-TW":"我們必須在截止日期前完成。"},{"en":"The deadline for applications is Friday.","zh-TW":"申請截止日期是週五。"},{"en":"We need to meet the deadline.","zh-TW":"我們需要趕上截止期限。"}]', '{"noun":"deadline"}', NULL, 3, 589),
(590, 'deal', '/diːl/', 'noun', '{"zh-TW":["交易；協議"],"en":["an agreement; a bargain"]}', NULL, 'big deal / deal with', '[{"en":"We made a deal.","zh-TW":"我們達成了一筆交易。"},{"en":"It''s not a big deal.","zh-TW":"這沒什麼大不了的。"}]', '{"verb":"deal","noun2":"dealer"}', NULL, 1, 590),
(591, 'dean', '/diːn/', 'noun', '{"zh-TW":["院長；系主任"],"en":["the head of a university department"]}', NULL, 'dean''s list / dean of students', '[{"en":"She was named to the dean''s list.","zh-TW":"她被列入院長嘉許名單。"},{"en":"The dean approved the new course.","zh-TW":"院長批准了新課程。"}]', NULL, NULL, 1, 591),
(592, 'debate', '/dɪˈbeɪt/', 'noun / verb', '{"zh-TW":["辯論；討論"],"en":["a formal discussion on a particular topic"]}', '{"prefix":{"text":"de-","meaning":"down/thoroughly (徹底)"},"root":{"text":"bat","meaning":"beat (打)"},"logic":"徹底地交鋒辯駁，即「辯論」。"}', 'public/heated debate; heated debate / public debate / open to debate', '[{"en":"There was a heated debate about the new policy.","zh-TW":"關於新政策有一場激烈的辯論。"},{"en":"They debated the issue for hours.","zh-TW":"他們就這個問題辯論了幾個小時。"},{"en":"There is a heated debate about immigration policy.","zh-TW":"關於移民政策有激烈的辯論。"},{"en":"The issue is still open to debate.","zh-TW":"這個議題仍有討論空間。"}]', '{"noun":"debate","verb":"debate","adjective":"debatable"}', NULL, 2, 592),
(593, 'debt', '/det/', 'noun', '{"zh-TW":["債務；欠款"],"en":["money that is owed to someone"]}', NULL, 'pay off/be in debt', '[{"en":"He is struggling to pay off his debts.","zh-TW":"他正努力償還債務。"},{"en":"The company is heavily in debt.","zh-TW":"這家公司負債累累。"}]', '{"noun":"debt/debtor"}', NULL, 1, 593),
(594, 'debug', '/diːˈbʌɡ/', 'verb', '{"zh-TW":["除錯"],"en":["to find and fix errors in computer code"]}', NULL, 'debug code / debug mode', '[{"en":"I spent hours debugging the code.","zh-TW":"我花了好幾個小時除錯。"},{"en":"Run it in debug mode.","zh-TW":"用除錯模式執行。"}]', '{"noun":"debugger","noun2":"debugging"}', NULL, 2, 594),
(595, 'decade', '/ˈdekeɪd/', 'noun', '{"zh-TW":["十年"],"en":["a period of ten years"]}', NULL, 'over the past decade', '[{"en":"The technology has evolved rapidly over the past decade.","zh-TW":"在過去十年中，技術迅速發展。"},{"en":"She spent a decade working overseas.","zh-TW":"她在海外工作了十年。"}]', '{"noun":"decade"}', NULL, 2, 595),
(596, 'decide', '/dɪˈsaɪd/', 'verb', '{"zh-TW":["決定"],"en":["to make a choice after thinking"]}', NULL, 'decide on / decide to', '[{"en":"We decided to postpone the launch.","zh-TW":"我們決定延後發布。"},{"en":"Have you decided on a venue?","zh-TW":"你決定好場地了嗎？"}]', '{"verb":"decide","noun":"decision","adjective":"decisive","adverb":"decisively"}', NULL, 2, 596),
(597, 'decline', '/dɪˈklaɪn/', 'verb / noun', '{"zh-TW":["下降；拒絕"],"en":["to decrease in quantity or importance; to politely refuse","to decrease","to politely refuse"]}', '{"prefix":{"text":"de-","meaning":"down (向下)"},"root":{"text":"cline","meaning":"lean (傾斜)"},"logic":"向下傾斜，即「下降」。"}', 'decline an offer/invitation; decline an invitation / sharp decline / decline in', '[{"en":"Sales have declined by 10% this quarter.","zh-TW":"本季度銷售額下降了10%。"},{"en":"She declined the job offer.","zh-TW":"她拒絕了工作邀請。"},{"en":"Sales have declined by 10% this quarter.","zh-TW":"本季銷售額下降了10%。"},{"en":"She politely declined the invitation.","zh-TW":"她禮貌地拒絕了邀請。"}]', '{"noun":"decline","verb":"decline"}', NULL, 3, 597),
(598, 'decrease', '/dɪˈkriːs/', 'verb / noun', '{"zh-TW":["減少；降低"],"en":["to become smaller or fewer in size or amount"]}', NULL, 'significant/steady decrease', '[{"en":"The number of employees decreased significantly.","zh-TW":"員工人數大幅減少。"},{"en":"There has been a decrease in demand.","zh-TW":"需求有所下降。"}]', '{"noun":"decrease","verb":"decrease"}', NULL, 3, 598),
(599, 'decree', '/dɪˈkriː/', 'noun', '{"zh-TW":["法令；判決"],"en":["an official order issued by a legal authority"]}', NULL, 'royal decree / issue a decree', '[{"en":"The president issued a decree.","zh-TW":"總統頒布了一項法令。"},{"en":"The court issued a divorce decree.","zh-TW":"法院發出了離婚判決。"}]', '{"verb":"decree"}', NULL, 2, 599);
INSERT INTO words (word_id, word, phonetic, part_of_speech, definitions_json, analysis_json, collocation, examples_json, word_family_json, secondary_meaning_note, difficulty, frequency_rank) VALUES
(600, 'dedicate', '/ˈdedɪkeɪt/', 'verb', '{"zh-TW":["奉獻；致力於"],"en":["to devote time or effort to a particular purpose","to devote time or effort to something"]}', '{"prefix":{"text":"de-","meaning":"completely (完全)"},"root":{"text":"dic","meaning":"declare (宣告)"},"suffix":{"text":"-ate","meaning":"make (使)"},"logic":"完全宣告投入，即「奉獻」。"}', 'dedicate oneself to; dedicate time to / dedicated employee', '[{"en":"She dedicated her life to medical research.","zh-TW":"她把一生奉獻給了醫學研究。"},{"en":"He is dedicated to improving customer service.","zh-TW":"他致力於改善客戶服務。"},{"en":"She dedicated her life to helping others.","zh-TW":"她一生奉獻於幫助他人。"},{"en":"He is a dedicated teacher.","zh-TW":"他是一位盡責的老師。"}]', '{"noun":"dedication","verb":"dedicate","adjective":"dedicated"}', NULL, 3, 600),
(601, 'deduct', '/dɪˈdʌkt/', 'verb', '{"zh-TW":["扣除；減去"],"en":["to subtract an amount from a total"]}', NULL, 'deduct from salary/taxes', '[{"en":"Tax is deducted from your salary automatically.","zh-TW":"稅款會自動從薪水中扣除。"},{"en":"You can deduct business expenses from income.","zh-TW":"你可以從收入中扣除商業費用。"}]', '{"noun":"deduction","verb":"deduct","adjective":"deductible"}', NULL, 2, 601),
(602, 'deep', '/diːp/', 'adjective', '{"zh-TW":["深的；深刻的","深的"],"en":["extending far down","very strong or intense","going far down from the surface"]}', NULL, 'deep analysis / in deep trouble; deep water / deep breath', '[{"en":"We need a deeper analysis of the data.","zh-TW":"我們需要更深入的數據分析。"},{"en":"The company is in deep financial trouble.","zh-TW":"公司陷入了嚴重的財務困境。"},{"en":"The river is very deep here.","zh-TW":"河在這裡非常深。"},{"en":"Take a deep breath and relax.","zh-TW":"深呼吸然後放鬆。"}]', '{"adjective":"deep","adverb":"deeply","verb":"deepen","noun":"depth"}', NULL, 1, 602),
(603, 'default', '/dɪˈfɔːlt/', 'noun / verb', '{"zh-TW":["違約；預設"],"en":["failure to fulfill an obligation; a preset value"]}', NULL, 'by default', '[{"en":"The company defaulted on its loan.","zh-TW":"該公司貸款違約了。"},{"en":"The settings are restored to default.","zh-TW":"設定已恢復為預設值。"}]', '{"noun":"default","verb":"default"}', NULL, 3, 603),
(604, 'defeat', '/dɪˈfiːt/', 'verb / noun', '{"zh-TW":["擊敗；失敗","擊敗；戰勝"],"en":["to win a victory over someone","to win against someone in a fight or game"]}', NULL, 'suffer/admit defeat; suffer a defeat / admit defeat', '[{"en":"They defeated the rival team 3-1.","zh-TW":"他們以3比1擊敗了對手。"},{"en":"He refused to admit defeat.","zh-TW":"他拒絕承認失敗。"},{"en":"They defeated the champions 2-1.","zh-TW":"他們以2比1擊敗了冠軍隊。"}]', '{"noun":"defeat","verb":"defeat"}', NULL, 2, 604),
(605, 'defend', '/dɪˈfend/', 'verb', '{"zh-TW":["防禦；辯護"],"en":["to protect from harm or danger"]}', NULL, 'defend against', '[{"en":"The lawyer defended her client in court.","zh-TW":"律師在法庭上為她的客戶辯護。"},{"en":"We must defend our market position.","zh-TW":"我們必須捍衛我們的市場地位。"}]', '{"noun":"defense/defendant","verb":"defend","adjective":"defensive"}', NULL, 2, 605),
(606, 'defendant', '/dɪˈfɛndənt/', 'noun', '{"zh-TW":["被告"],"en":["a person accused in a court of law"]}', NULL, 'the defendant pleaded / defendant''s rights', '[{"en":"The defendant pleaded not guilty.","zh-TW":"被告答辯無罪。"},{"en":"The defendant has the right to an attorney.","zh-TW":"被告有權請律師。"}]', '{"verb":"defend","noun2":"defense"}', NULL, 3, 606),
(607, 'defer', '/dɪˈfɜːr/', 'verb', '{"zh-TW":["推遲；順從"],"en":["to postpone; to yield to another''s opinion"]}', NULL, 'defer payment/judgment', '[{"en":"Payment has been deferred until next month.","zh-TW":"付款已延遲到下個月。"},{"en":"I defer to your expertise on this matter.","zh-TW":"在這件事上我尊重你的專業意見。"}]', '{"noun":"deferral","verb":"defer"}', NULL, 2, 607),
(608, 'deficit', '/ˈdefɪsɪt/', 'noun', '{"zh-TW":["赤字；不足"],"en":["the amount by which something falls short"]}', NULL, 'budget/trade deficit', '[{"en":"The government is trying to reduce the budget deficit.","zh-TW":"政府正在試圖減少預算赤字。"},{"en":"The trade deficit widened last year.","zh-TW":"去年貿易逆差擴大了。"}]', '{"noun":"deficit"}', NULL, 3, 608),
(609, 'define', '/dɪˈfaɪn/', 'verb', '{"zh-TW":["定義；界定"],"en":["to state the exact meaning of something"]}', NULL, 'clearly define', '[{"en":"Please define your objectives clearly.","zh-TW":"請清楚地界定你的目標。"},{"en":"The contract defines the terms of employment.","zh-TW":"合約界定了僱用條件。"}]', '{"noun":"definition","verb":"define","adjective":"definite"}', NULL, 2, 609),
(610, 'degree', '/dɪˈɡriː/', 'noun', '{"zh-TW":["學位；程度；度","學位；程度"],"en":["an academic qualification","an amount or level","a qualification from a university"]}', NULL, 'to a degree / master''s degree; bachelor''s degree / to some degree', '[{"en":"She has a master''s degree in finance.","zh-TW":"她有金融碩士學位。"},{"en":"To what degree is this accurate?","zh-TW":"這在多大程度上是準確的？"},{"en":"She has a degree in engineering.","zh-TW":"她有工程學位。"},{"en":"To some degree, I agree with you.","zh-TW":"在某種程度上，我同意你。"}]', '{"noun":"degree"}', NULL, 2, 610),
(611, 'delay', '/dɪˈleɪ/', 'verb / noun', '{"zh-TW":["延遲；耽擱"],"en":["to make something happen later than expected"]}', NULL, 'without delay', '[{"en":"The flight was delayed by two hours.","zh-TW":"航班延誤了兩個小時。"},{"en":"Please respond without delay.","zh-TW":"請立即回覆。"}]', '{"noun":"delay","verb":"delay","adjective":"delayed"}', NULL, 2, 611),
(612, 'delegate', '/ˈdelɪɡeɪt/', 'verb / noun', '{"zh-TW":["委派；代表"],"en":["to give a task or responsibility to someone else"]}', NULL, 'delegate authority/tasks', '[{"en":"A good manager knows how to delegate tasks.","zh-TW":"好的管理者知道如何委派任務。"},{"en":"Each country sent a delegate to the conference.","zh-TW":"每個國家都派了代表出席會議。"}]', '{"noun":"delegate/delegation","verb":"delegate"}', NULL, 3, 612),
(613, 'deliberate', '/dɪˈlɪbərət/', 'adjective / verb', '{"zh-TW":["故意的；審慎的"],"en":["done intentionally; to think carefully","done consciously and intentionally"]}', '{"prefix":{"text":"de-","meaning":"completely (完全)"},"root":{"text":"liber","meaning":"weigh (衡量)"},"suffix":{"text":"-ate","meaning":"having (具有)"},"logic":"完全經過衡量的，即「審慎的」或「故意的」。"}', 'deliberate action/decision; deliberate action / deliberate decision', '[{"en":"It was a deliberate attempt to mislead investors.","zh-TW":"這是故意誤導投資者的行為。"},{"en":"The jury deliberated for three days.","zh-TW":"陪審團審議了三天。"},{"en":"It was a deliberate attempt to mislead the public.","zh-TW":"這是故意誤導公眾的企圖。"},{"en":"She made a deliberate choice to change careers.","zh-TW":"她審慎地決定轉換職業。"}]', '{"noun":"deliberation","verb":"deliberate","adjective":"deliberate","adverb":"deliberately"}', NULL, 4, 613),
(614, 'deliver', '/dɪˈlɪvər/', 'verb', '{"zh-TW":["遞送；發表"],"en":["to bring goods to a destination; to give a speech","to take something to a person or place"]}', NULL, 'deliver goods/a speech; deliver a speech / deliver goods', '[{"en":"The package will be delivered tomorrow.","zh-TW":"包裹明天會送達。"},{"en":"She delivered an inspiring presentation.","zh-TW":"她發表了一場鼓舞人心的演講。"},{"en":"The package was delivered this morning.","zh-TW":"包裹今天早上送到了。"},{"en":"She delivered an inspiring speech.","zh-TW":"她發表了一場鼓舞人心的演講。"}]', '{"noun":"delivery","verb":"deliver"}', NULL, 3, 614),
(615, 'delivery', '/dɪˈlɪvəri/', 'noun', '{"zh-TW":["遞送；交付"],"en":["the act of bringing goods to a person"]}', '{"prefix":{"text":"de-","meaning":"away (離開)"},"root":{"text":"liver","meaning":"free (釋放)"},"logic":"釋放出去的行為，即「遞送」。"}', 'free delivery / express delivery', '[{"en":"Delivery takes three to five business days.","zh-TW":"遞送需要三到五個工作天。"},{"en":"We offer free delivery on orders over $50.","zh-TW":"滿50美元免運費。"}]', '{"verb":"deliver"}', NULL, 3, 615),
(616, 'demand', '/dɪˈmænd/', 'noun / verb', '{"zh-TW":["需求；要求"],"en":["a strong request; the desire for goods or services","a strong request; the desire for goods"]}', NULL, 'meet/supply demand; in demand / supply and demand', '[{"en":"Consumer demand for organic food is growing.","zh-TW":"消費者對有機食品的需求正在增長。"},{"en":"Workers demanded higher wages.","zh-TW":"工人要求更高的工資。"},{"en":"There''s a high demand for nurses.","zh-TW":"對護士的需求很高。"},{"en":"Supply and demand affect prices.","zh-TW":"供需影響價格。"}]', '{"noun":"demand","verb":"demand","adjective":"demanding"}', NULL, 2, 616),
(617, 'democracy', '/dɪˈmɒkrəsi/', 'noun', '{"zh-TW":["民主；民主制度","民主"],"en":["government by the people","a system of government by the people"]}', '{"root":{"text":"demo","meaning":"people (人民)"},"suffix":{"text":"cracy","meaning":"rule (統治)"},"logic":"人民統治，即「民主」。"}', 'democratic society / promote democracy; promote democracy / democratic process', '[{"en":"Democracy gives everyone a voice.","zh-TW":"民主賦予每個人發言權。"},{"en":"They fought to protect democracy.","zh-TW":"他們為保護民主而戰。"},{"en":"Democracy gives citizens the right to vote.","zh-TW":"民主賦予公民投票權。"},{"en":"The country transitioned to democracy peacefully.","zh-TW":"該國和平過渡到民主體制。"}]', '{"adjective":"democratic","noun2":"democrat"}', NULL, 3, 617),
(618, 'demonstrate', '/ˈdemənstreɪt/', 'verb', '{"zh-TW":["展示；證明"],"en":["to show clearly; to prove","to show clearly","to prove by giving evidence"]}', '{"prefix":{"text":"de-","meaning":"completely (完全)"},"root":{"text":"monstr","meaning":"show (展示)"},"suffix":{"text":"-ate","meaning":"make (使)"},"logic":"完全展示出來，即「證明」。"}', 'demonstrate ability/skills; demonstrate how / clearly demonstrate', '[{"en":"The data demonstrates a clear trend.","zh-TW":"數據顯示了一個明確的趨勢。"},{"en":"She demonstrated how to use the software.","zh-TW":"她展示了如何使用該軟體。"},{"en":"The experiment demonstrates the theory.","zh-TW":"這個實驗證明了該理論。"},{"en":"Let me demonstrate how to use this tool.","zh-TW":"讓我示範如何使用這個工具。"}]', '{"noun":"demonstration","verb":"demonstrate"}', NULL, 4, 618),
(619, 'deny', '/dɪˈnaɪ/', 'verb', '{"zh-TW":["否認；拒絕"],"en":["to declare something untrue; to refuse","to refuse to admit the truth of","to refuse to give"]}', '{"prefix":{"text":"de-","meaning":"away (離開)"},"root":{"text":"ny","meaning":"say no (說不)"},"logic":"說不，即「否認」。"}', 'deny access/responsibility; deny the accusation / deny access / cannot deny', '[{"en":"He denied any involvement in the scandal.","zh-TW":"他否認與醜聞有任何關係。"},{"en":"Access was denied due to security reasons.","zh-TW":"由於安全原因，訪問被拒絕。"},{"en":"He denied all the accusations.","zh-TW":"他否認了所有指控。"},{"en":"They denied him access to the building.","zh-TW":"他們拒絕讓他進入大樓。"}]', '{"noun":"denial","verb":"deny"}', NULL, 1, 619),
(620, 'depart', '/dɪˈpɑːrt/', 'verb', '{"zh-TW":["離開；出發"],"en":["to leave, especially on a journey"]}', NULL, 'depart from', '[{"en":"The train departs at 8:00 AM.","zh-TW":"火車早上8點出發。"},{"en":"She departed from the original plan.","zh-TW":"她偏離了原來的計畫。"}]', '{"noun":"departure","verb":"depart"}', NULL, 2, 620),
(621, 'department', '/dɪˈpɑːrtmənt/', 'noun', '{"zh-TW":["部門；科系"],"en":["a division of a large organization or store"]}', '{"prefix":{"text":"de-","meaning":"apart (分開)"},"root":{"text":"part","meaning":"part (部分)"},"suffix":{"text":"-ment","meaning":"result (結果)"},"logic":"分開成各部分的結果，即「部門」。"}', 'department store / sales department', '[{"en":"The electronics department is on the second floor.","zh-TW":"電子產品部在二樓。"},{"en":"She works in the marketing department.","zh-TW":"她在行銷部門工作。"}]', '{"adjective":"departmental"}', NULL, 4, 621),
(622, 'depend', '/dɪˈpend/', 'verb', '{"zh-TW":["依賴；取決於"],"en":["to rely on; to be determined by","to rely on","to be determined by"]}', '{"prefix":{"text":"de-","meaning":"from (從)"},"root":{"text":"pend","meaning":"hang (懸掛)"},"logic":"懸掛在某物上依靠它，即「依賴」。"}', 'depend on/upon; depend on / it depends / depending on', '[{"en":"The outcome depends on several factors.","zh-TW":"結果取決於幾個因素。"},{"en":"You can depend on her to finish the task.","zh-TW":"你可以依賴她完成任務。"},{"en":"The outcome depends on many factors.","zh-TW":"結果取決於很多因素。"},{"en":"Children depend on their parents.","zh-TW":"孩子依賴他們的父母。"}]', '{"noun":"dependence/dependency","verb":"depend","adjective":"dependent/dependable","adjective2":"dependable"}', NULL, 2, 622),
(623, 'deposit', '/dɪˈpɑːzɪt/', 'noun / verb', '{"zh-TW":["存款；押金；存放"],"en":["money placed in a bank; to put money into an account"]}', NULL, 'make a deposit', '[{"en":"I need to make a deposit at the bank.","zh-TW":"我需要去銀行存款。"},{"en":"A deposit of $500 is required.","zh-TW":"需要500美元的押金。"}]', '{"noun":"deposit","verb":"deposit"}', NULL, 3, 623),
(624, 'depreciate', '/dɪˈpriːʃieɪt/', 'verb', '{"zh-TW":["貶值；折舊"],"en":["to decrease in value over time"]}', NULL, 'depreciate in value', '[{"en":"The car depreciated quickly after purchase.","zh-TW":"這輛車購買後迅速貶值。"},{"en":"Equipment depreciates over its useful life.","zh-TW":"設備在其使用壽命內折舊。"}]', '{"noun":"depreciation","verb":"depreciate"}', NULL, 4, 624),
(625, 'depreciation', '/dɪˌpriːʃiˈeɪʃən/', 'noun', '{"zh-TW":["折舊；貶值"],"en":["a decrease in value over time"]}', NULL, 'asset depreciation / annual depreciation', '[{"en":"We account for annual depreciation of equipment.","zh-TW":"我們計算設備的年度折舊。"},{"en":"Currency depreciation affects import costs.","zh-TW":"貨幣貶值影響進口成本。"}]', '{"noun":"depreciation","verb":"depreciate"}', NULL, 4, 625),
(626, 'depressed', '/dɪˈprest/', 'adjective', '{"zh-TW":["沮喪的；憂鬱的"],"en":["in a state of unhappiness"]}', '{"prefix":{"text":"de-","meaning":"down (向下)"},"root":{"text":"press","meaning":"press (壓)"},"suffix":{"text":"-ed","meaning":"state (狀態)"},"logic":"被向下壓的狀態，即「沮喪的」。"}', 'feel depressed / clinically depressed', '[{"en":"He felt depressed after losing his job.","zh-TW":"失業後他感到很沮喪。"},{"en":"If you feel depressed, seek professional help.","zh-TW":"如果你感到憂鬱，請尋求專業協助。"}]', '{"noun":"depression","verb":"depress","adjective":"depressing"}', NULL, 3, 626),
(627, 'derive', '/dɪˈraɪv/', 'verb', '{"zh-TW":["源自；獲得"],"en":["to obtain from a source; to originate"]}', NULL, 'derive from', '[{"en":"The word derives from Latin.","zh-TW":"這個詞源自拉丁語。"},{"en":"We derive great satisfaction from our work.","zh-TW":"我們從工作中獲得極大的滿足感。"}]', '{"noun":"derivation/derivative","verb":"derive"}', NULL, 2, 627),
(628, 'describe', '/dɪˈskraɪb/', 'verb', '{"zh-TW":["描述；形容","描述"],"en":["to give a detailed account of something","to say what something is like"]}', NULL, 'describe as; describe as / hard to describe', '[{"en":"Can you describe the suspect?","zh-TW":"你能描述一下嫌疑人嗎？"},{"en":"She described the experience as life-changing.","zh-TW":"她形容這次經歷改變了她的人生。"},{"en":"Can you describe what happened?","zh-TW":"你能描述發生了什麼嗎？"},{"en":"Words cannot describe my feelings.","zh-TW":"言語無法描述我的感受。"}]', '{"noun":"description","verb":"describe","adjective":"descriptive"}', NULL, 3, 628),
(629, 'deserve', '/dɪˈzɜːrv/', 'verb', '{"zh-TW":["值得；應得"],"en":["to be worthy of something","to be worthy of reward or punishment"]}', '{"prefix":{"text":"de-","meaning":"completely (完全)"},"root":{"text":"serve","meaning":"serve (服務)"},"logic":"完全服務付出而應得的。"}', 'deserve recognition/attention; deserve recognition / deserve better / well-deserved', '[{"en":"She deserves a promotion for her hard work.","zh-TW":"她努力工作，值得升職。"},{"en":"This issue deserves more attention.","zh-TW":"這個問題值得更多關注。"},{"en":"She deserves a promotion for her hard work.","zh-TW":"她努力工作，值得升遷。"},{"en":"The team deserves recognition for their efforts.","zh-TW":"團隊的努力值得肯定。"}]', '{"adjective":"deserving","verb":"deserve"}', NULL, 3, 629),
(630, 'design', '/dɪˈzaɪn/', 'noun / verb', '{"zh-TW":["設計；計畫","設計"],"en":["to plan and create something; a drawing or plan","the art of making plans for something"]}', NULL, 'design a product/system; graphic design / by design', '[{"en":"She designed the company''s new logo.","zh-TW":"她設計了公司的新標誌。"},{"en":"The building has an innovative design.","zh-TW":"這棟建築有創新的設計。"},{"en":"She studied fashion design.","zh-TW":"她學了時裝設計。"}]', '{"noun":"design/designer","verb":"design","noun2":"designer"}', NULL, 2, 630),
(631, 'designate', '/ˈdezɪɡneɪt/', 'verb', '{"zh-TW":["指定；指派"],"en":["to officially assign a status or name"]}', NULL, 'designate as', '[{"en":"This area has been designated as a no-smoking zone.","zh-TW":"此區域已被指定為禁菸區。"},{"en":"She was designated as team leader.","zh-TW":"她被指派為團隊負責人。"}]', '{"noun":"designation","verb":"designate","adjective":"designated"}', NULL, 3, 631),
(632, 'desire', '/dɪˈzaɪər/', 'noun / verb', '{"zh-TW":["渴望；願望","渴望；慾望"],"en":["a strong wish for something","a strong feeling of wanting something"]}', NULL, 'express a desire; desire for / heart''s desire', '[{"en":"She expressed a desire to travel abroad.","zh-TW":"她表達了出國旅行的願望。"},{"en":"The desired outcome was achieved.","zh-TW":"達到了預期的結果。"},{"en":"He has a strong desire to succeed.","zh-TW":"他有強烈的成功慾望。"},{"en":"She fulfilled her heart''s desire.","zh-TW":"她實現了她內心的渴望。"}]', '{"noun":"desire","verb":"desire","adjective":"desirable/desired"}', NULL, 2, 632),
(633, 'desk', '/dɛsk/', 'noun', '{"zh-TW":["書桌；辦公桌"],"en":["a table for working at"]}', NULL, 'front desk / help desk', '[{"en":"Please check in at the front desk.","zh-TW":"請在前台登記。"},{"en":"Contact the help desk for IT issues.","zh-TW":"如有IT問題請聯繫服務台。"}]', '{"noun":"desk"}', NULL, 1, 633),
(634, 'despite', '/dɪˈspaɪt/', 'preposition', '{"zh-TW":["儘管；不顧"],"en":["without being affected by; in spite of"]}', NULL, 'despite the fact that', '[{"en":"Despite the rain, the event was a success.","zh-TW":"儘管下雨，活動還是很成功。"},{"en":"She succeeded despite many obstacles.","zh-TW":"儘管有許多障礙，她還是成功了。"}]', NULL, NULL, 3, 634),
(635, 'destination', '/ˌdestɪˈneɪʃən/', 'noun', '{"zh-TW":["目的地"],"en":["the place to which someone is going"]}', '{"root":{"text":"destin","meaning":"determine (決定)"},"suffix":{"text":"-ation","meaning":"place (地方)"},"logic":"決定要去的地方，即「目的地」。"}', 'tourist/popular destination; popular destination / final destination / travel destination', '[{"en":"We arrived at our destination on time.","zh-TW":"我們準時到達了目的地。"},{"en":"Paris is a popular tourist destination.","zh-TW":"巴黎是熱門的旅遊目的地。"},{"en":"Paris is a popular tourist destination.","zh-TW":"巴黎是熱門旅遊目的地。"},{"en":"We arrived at our destination at noon.","zh-TW":"我們中午抵達目的地。"}]', '{"noun":"destination"}', NULL, 4, 635),
(636, 'destroy', '/dɪˈstrɔɪ/', 'verb', '{"zh-TW":["摧毀；破壞"],"en":["to damage something so badly it no longer exists"]}', NULL, 'destroy completely / destroy evidence', '[{"en":"The fire destroyed the building.","zh-TW":"大火摧毀了建築物。"},{"en":"War destroys lives and communities.","zh-TW":"戰爭摧毀生命和社區。"}]', '{"noun":"destruction","adjective":"destructive"}', NULL, 3, 636),
(637, 'detail', '/ˈdiːteɪl/', 'noun', '{"zh-TW":["細節"],"en":["a small individual fact or item"]}', NULL, 'in detail / pay attention to detail', '[{"en":"Please explain in more detail.","zh-TW":"請更詳細地解釋。"},{"en":"She pays attention to every detail.","zh-TW":"她注意每一個細節。"}]', '{"adjective":"detailed"}', NULL, 2, 637),
(638, 'detect', '/dɪˈtekt/', 'verb', '{"zh-TW":["偵測；發現"],"en":["to discover or notice something","to discover the presence of something"]}', '{"prefix":{"text":"de-","meaning":"away (除去)"},"root":{"text":"tect","meaning":"cover (覆蓋)"},"logic":"把覆蓋物移除而發現，即「偵測」。"}', 'detect a problem/error; detect a problem / detect changes', '[{"en":"The system detected an error in the data.","zh-TW":"系統偵測到資料中的錯誤。"},{"en":"Cancer can be treated if detected early.","zh-TW":"癌症如果早期發現可以治療。"},{"en":"The sensor can detect small changes in temperature.","zh-TW":"感測器能偵測到微小的溫度變化。"},{"en":"Police detected traces of the substance.","zh-TW":"警方偵測到該物質的痕跡。"}]', '{"noun":"detection/detector","verb":"detect","adjective":"detectable","noun2":"detector"}', NULL, 2, 638),
(639, 'determine', '/dɪˈtɜːrmɪn/', 'verb', '{"zh-TW":["決定；確定"],"en":["to find out; to be the cause of","to find out or establish exactly"]}', NULL, 'determine the cause/outcome; determine the cause / determined to', '[{"en":"We need to determine the cause of the problem.","zh-TW":"我們需要確定問題的原因。"},{"en":"Your score determines your final grade.","zh-TW":"你的分數決定你的最終成績。"},{"en":"We need to determine the cause.","zh-TW":"我們需要確定原因。"},{"en":"She''s determined to succeed.","zh-TW":"她決心要成功。"}]', '{"noun":"determination","verb":"determine","adjective":"determined"}', NULL, 3, 639),
(640, 'determined', '/dɪˈtɜːrmɪnd/', 'adjective', '{"zh-TW":["堅定的；下定決心的"],"en":["having made a firm decision and being resolved"]}', '{"prefix":{"text":"de-","meaning":"completely (完全)"},"root":{"text":"termin","meaning":"limit/end (界限/結束)"},"suffix":{"text":"-ed","meaning":"state (狀態)"},"logic":"完全確定了界限方向的，即「堅定的」。"}', 'determined to succeed / a determined effort', '[{"en":"She is determined to finish the marathon.","zh-TW":"她下定決心要跑完馬拉松。"},{"en":"He made a determined effort to improve.","zh-TW":"他堅定地努力改進。"}]', '{"noun":"determination","verb":"determine"}', NULL, 4, 640),
(641, 'devastating', '/ˈdevəsteɪtɪŋ/', 'adjective', '{"zh-TW":["毀滅性的"],"en":["causing severe damage or destruction"]}', '{"prefix":{"text":"de-","meaning":"completely (完全)"},"root":{"text":"vast","meaning":"empty/waste (荒廢)"},"suffix":{"text":"-ating","meaning":"causing (造成)"},"logic":"造成完全荒廢的，即「毀滅性的」。"}', 'devastating effect / devastating news', '[{"en":"The hurricane had a devastating impact on the town.","zh-TW":"颶風對城鎮造成了毀滅性的影響。"},{"en":"The news was devastating for the family.","zh-TW":"這個消息對這家人來說是毀滅性的打擊。"}]', '{"verb":"devastate","noun":"devastation"}', NULL, 4, 641),
(642, 'develop', '/dɪˈveləp/', 'verb', '{"zh-TW":["發展；開發","開發；發展"],"en":["to grow or cause to grow; to create","to grow or create something over time"]}', NULL, 'develop a plan/product; develop skills / develop a plan', '[{"en":"The company is developing a new product.","zh-TW":"公司正在開發新產品。"},{"en":"Skills develop with practice.","zh-TW":"技能通過練習而發展。"},{"en":"The company developed a new product.","zh-TW":"公司開發了一款新產品。"},{"en":"Children develop at different rates.","zh-TW":"孩子們的發展速度不同。"}]', '{"noun":"development/developer","verb":"develop","noun2":"developer"}', NULL, 3, 642),
(643, 'developer', '/dɪˈvɛləpər/', 'noun', '{"zh-TW":["開發者"],"en":["a person who creates software"]}', NULL, 'software developer / web developer', '[{"en":"She''s a software developer.","zh-TW":"她是一名軟體開發者。"},{"en":"The developer fixed the bug quickly.","zh-TW":"開發者很快修復了錯誤。"}]', '{"verb":"develop","noun2":"development"}', NULL, 3, 643),
(644, 'device', '/dɪˈvaɪs/', 'noun', '{"zh-TW":["裝置；設備"],"en":["a piece of equipment made for a particular purpose","a piece of equipment made for a purpose"]}', NULL, 'electronic/mobile device; electronic device / mobile device', '[{"en":"This device can monitor heart rate.","zh-TW":"這個裝置可以監測心率。"},{"en":"Please turn off all electronic devices.","zh-TW":"請關閉所有電子設備。"},{"en":"Turn off all electronic devices.","zh-TW":"關閉所有電子設備。"},{"en":"The device connects via USB.","zh-TW":"這個裝置透過USB連接。"}]', '{"noun":"device"}', NULL, 2, 644),
(645, 'devote', '/dɪˈvoʊt/', 'verb', '{"zh-TW":["奉獻；投入"],"en":["to give time or resources to something","to give time, effort, or resources to something"]}', '{"prefix":{"text":"de-","meaning":"completely (完全)"},"root":{"text":"vote","meaning":"vow (發誓)"},"logic":"完全發誓投入，即「奉獻」。"}', 'devote time/energy to; devote time to / devote oneself to', '[{"en":"He devoted his career to public service.","zh-TW":"他把職業生涯奉獻給了公共服務。"},{"en":"She devotes two hours daily to exercise.","zh-TW":"她每天投入兩小時運動。"},{"en":"He devoted his career to scientific research.","zh-TW":"他將職業生涯奉獻給科學研究。"},{"en":"She devotes several hours a week to volunteering.","zh-TW":"她每週投入幾個小時做志工。"}]', '{"noun":"devotion","verb":"devote","adjective":"devoted"}', NULL, 2, 645),
(646, 'diagnose', '/ˌdaɪəɡˈnoʊz/', 'verb', '{"zh-TW":["診斷"],"en":["to identify a disease or problem"]}', NULL, 'diagnose a condition', '[{"en":"The doctor diagnosed him with diabetes.","zh-TW":"醫生診斷他患有糖尿病。"},{"en":"The technician diagnosed the issue quickly.","zh-TW":"技術人員很快診斷出了問題。"}]', '{"noun":"diagnosis","verb":"diagnose","adjective":"diagnostic"}', NULL, 3, 646),
(647, 'dictionary', '/ˈdɪkʃənɛri/', 'noun', '{"zh-TW":["字典"],"en":["a book that lists words and their meanings"]}', NULL, 'look up in a dictionary / online dictionary', '[{"en":"Use a dictionary to check the spelling.","zh-TW":"用字典查看拼寫。"},{"en":"Online dictionaries are very convenient.","zh-TW":"線上字典非常方便。"}]', '{"noun":"dictionary"}', NULL, 4, 647),
(648, 'die', '/daɪ/', 'verb', '{"zh-TW":["死亡"],"en":["to stop living"]}', NULL, 'die of / die out', '[{"en":"Many soldiers died in the war.","zh-TW":"許多士兵在戰爭中死亡。"},{"en":"The species is dying out.","zh-TW":"這個物種正在滅絕。"}]', '{"noun":"death","adjective":"dead"}', NULL, 1, 648),
(649, 'differ', '/ˈdɪfər/', 'verb', '{"zh-TW":["不同；相異"],"en":["to be unlike or distinct"]}', NULL, 'differ from/in', '[{"en":"Opinions differ on this issue.","zh-TW":"對這個問題意見不一。"},{"en":"The two products differ significantly in quality.","zh-TW":"這兩個產品在品質上有很大差異。"}]', '{"noun":"difference","verb":"differ","adjective":"different","adverb":"differently"}', NULL, 2, 649);